func phaseLabel(phase string, reviewing bool) string {
	if reviewing && phase == "study" {
		return "Revisão"
	}
	switch phase {
	case "quiz":
		return "Questões"
	case "results":
		return "Concluído"
	default:
		return "Estudando"
	}
}

func phaseLamp(phase string, reviewing bool) bool {
	if reviewing && phase == "study" {
		return true
	}
	return phase == "quiz"
}

